func (s *Store) loadAll() error {
	if _, err := os.Stat(s.baseDir); os.IsNotExist(err) {
		return os.MkdirAll(s.baseDir, 0755)
	}

	return filepath.WalkDir(s.baseDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
